import reference from '@shared/fixtures/kinematics-reference.json';
import type { AngleTriple, ArmGeometry, RobotConfig } from '@/types/robot';

/** Typed view of shared/fixtures/kinematics-reference.json (generated by the backend). */
export interface ReferenceCase {
  name: string;
  geometry: ArmGeometry;
  jointAngles: AngleTriple;
  expected: {
    frames: number[][][];
    jointPositions: number[][];
    jointAxes: number[][];
    endEffectorPosition: number[];
  };
}

export const REFERENCE = reference as unknown as {
  tolerance: number;
  defaultRobot: RobotConfig;
  constraints: {
    minLinkLength: number;
    minBaseHeight: number;
    maxLength: number;
    angleBound: number;
  };
  cases: ReferenceCase[];
};
